import React from 'react';
import { Helmet } from 'react-helmet-async';
export default function Seo({title,description,path='/',type='website',schema}){const canonical=`https://beyond31.online${path}`;const fullTitle=title?`${title} — Beyond31`:'Beyond31 — Projets de Huriel Nguimbi';const desc=description||'Beyond31 rassemble les projets numériques de Huriel Nguimbi.';return <Helmet><html lang="fr"/><title>{fullTitle}</title><meta name="description" content={desc}/><link rel="canonical" href={canonical}/><meta property="og:type" content={type}/><meta property="og:title" content={fullTitle}/><meta property="og:description" content={desc}/><meta property="og:url" content={canonical}/><meta property="og:site_name" content="Beyond31"/><meta property="og:image" content="https://beyond31.online/images/beyond31_logo.png"/><meta name="twitter:card" content="summary_large_image"/><meta name="twitter:title" content={fullTitle}/><meta name="twitter:description" content={desc}/>{schema&&<script type="application/ld+json">{JSON.stringify(schema)}</script>}</Helmet>}
